import{_ as t,o as a,c as s,a1 as n}from"./chunks/framework.CiMD_7j0.js";const b=JSON.parse('{"title":"Platform Overview","description":"","frontmatter":{"AIGC":{"ContentProducer":"001191110102MAD55U9H0F10002","ContentPropagator":"001191110102MAD55U9H0F10002","Label":"1","ProduceID":"8dcb57b4-c4ca-46b1-8e84-16551d2cb4f4","PropagateID":"8dcb57b4-c4ca-46b1-8e84-16551d2cb4f4","ReservedCode1":"d515f32c-6bd0-45f7-bbf3-c03eec3549c3","ReservedCode2":"d515f32c-6bd0-45f7-bbf3-c03eec3549c3"}},"headers":[],"relativePath":"en/guide/python/overview.md","filePath":"en/guide/python/overview.md","lastUpdated":null}'),i={name:"en/guide/python/overview.md"};function d(o,e,r,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="platform-overview" tabindex="-1">Platform Overview <a class="header-anchor" href="#platform-overview" aria-label="Permalink to &quot;Platform Overview&quot;">​</a></h1><p>ApeAdmin is a decoupled admin framework: the backend is built on FastAPI with SQLAlchemy 2.0 async sessions, and the frontend uses Vue 3, TypeScript, Vite and Element Plus. Business capabilities are extended via plugins; the core only handles common authentication, permissions, menus, logging, data access and AI capabilities.</p><h2 id="what-it-solves" tabindex="-1">What It Solves <a class="header-anchor" href="#what-it-solves" aria-label="Permalink to &quot;What It Solves&quot;">​</a></h2><ul><li>Unified users, roles, menus and API permissions to support admin business scenarios.</li><li>Plugin packages isolate business code with runtime enable/disable and resource cleanup.</li><li>MCP exposes authorizable admin capabilities to AI agents.</li><li>Unified error responses, request tracing and operation logs reduce troubleshooting cost.</li></ul><h2 id="runtime-boundary" tabindex="-1">Runtime Boundary <a class="header-anchor" href="#runtime-boundary" aria-label="Permalink to &quot;Runtime Boundary&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser</span></span>
<span class="line"><span>  ├─ Vue Admin Panel (/)</span></span>
<span class="line"><span>  └─ Apehub_web Website (/apehub-web)</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          └─ FastAPI (/api/v1)</span></span>
<span class="line"><span>               ├─ Core APIs: auth / user / role / menu / dept / plugin</span></span>
<span class="line"><span>               ├─ MCP: tools / resources / prompts / audit-logs</span></span>
<span class="line"><span>               └─ Plugin APIs: mounted by the plugin itself</span></span></code></pre></div><p>Apehub_web is a regular ApeAdmin plugin: it provides the website, marketplace, developer center and site admin APIs, but does not change the core routing rules. When enabled it mounts <code>/api/v1/apehub-web</code> and <code>/apehub-web</code>; when disabled the plugin manager removes its runtime resources and hides its menus.</p><h2 id="directory-map" tabindex="-1">Directory Map <a class="header-anchor" href="#directory-map" aria-label="Permalink to &quot;Directory Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Directory</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>backend/src/api</code></td><td>Core HTTP routes</td></tr><tr><td><code>backend/src/core</code></td><td>Config, security, dependency injection, middleware, seed data</td></tr><tr><td><code>backend/src/db</code></td><td>Async engine, sessions and database initialization</td></tr><tr><td><code>backend/src/models</code></td><td>Core ORM models</td></tr><tr><td><code>backend/src/crud</code></td><td>Generic CRUD and RBAC data operations</td></tr><tr><td><code>backend/src/plugins</code></td><td>Plugin interface, discovery, install, hot toggling and resource tracking</td></tr><tr><td><code>backend/src/mcp</code></td><td>MCP tools, resources, prompts and auditing</td></tr><tr><td><code>backend/src/ai</code></td><td>Multi-model chat and tool-calling loops</td></tr><tr><td><code>frontend/src/router</code></td><td>Static routes, dynamic menu routes and permission guards</td></tr><tr><td><code>frontend/src/views</code></td><td>Vue pages; paths must match the menu <code>component</code></td></tr></tbody></table><h2 id="key-principles" tabindex="-1">Key Principles <a class="header-anchor" href="#key-principles" aria-label="Permalink to &quot;Key Principles&quot;">​</a></h2><ol><li>Core capabilities live in <code>backend/src</code>; business capabilities live in plugin directories.</li><li>Plugin menus, APIs, tables and static assets must use their own namespaces.</li><li>Page permissions only improve the frontend experience; backend APIs must re-check permissions.</li><li>Production uses migration scripts; <code>init_db()</code> is for first-time development startup only.</li></ol>`,11)])])}const h=t(i,[["render",d]]);export{b as __pageData,h as default};
